tool_input.content:
// Scratch verification harness (NOT part of the deliverable).
const fs = require('fs');
const P = '/home/zmhel/gitrepos/learn-ai/eval01/runs/.gen-work/t35/game.html';
const src = fs.readFileSync(P, 'utf8');

console.log('=== static checks ===');
console.log('file bytes            :', src.length);
console.log('Math.random used      :', /Math\.random/.test(src));
console.log('web storage used      :', /localStorage|sessionStorage|indexedDB|document\.cookie/.test(src));
console.log('external url          :', /https?:\/\//.test(src));
console.log('network calls         :', /fetch\(|XMLHttpRequest|WebSocket|import\(/.test(src));
console.log('script tags           :', (src.match(/<script/g) || []).length);
console.log('style tags            :', (src.match(/<style/g) || []).length);
console.log('link/img tags         :', (src.match(/<link|<img/g) || []).length);

const m = src.match(/<script>([\s\S]*)<\/script>/);
const code = m[1];
const mod = { exports: {} };
const fn = new Function('module', 'exports', 'window', 'document', 'performance', code);
fn(mod, mod.exports, undefined, undefined, undefined);
const A = mod.exports;
console.log('exports               :', Object.keys(A).join(', '));

console.log('\n=== unit tests ===');
const t = A.runTests();
t.results.forEach((r, i) => {
  console.log((r.pass ? 'PASS ' : 'FAIL ') + String(i + 1).padStart(2, '0') + '. ' + r.name +
    (r.detail ? '\n        -> ' + r.detail : ''));
});
console.log('---> ' + t.passed + ' / ' + t.total + ' passed');

console.log('\n=== benchmark determinism ===');
for (const seed of [1337, 4242, 7]) {
  const a = A.benchmark(seed, 200), b = A.benchmark(seed, 200);
  console.log('seed ' + String(seed).padEnd(6) + ' hash ' + a.hash + ' / ' + b.hash +
    (a.hash === b.hash ? '  OK' : '  MISMATCH') +
    ' | turns ' + a.turns + ' pop ' + a.pop + ' res ' + a.research +
    ' bld ' + a.buildings + ' morale ' + a.morale + ' alive ' + a.alive +
    ' score ' + A.score(a.state).total);
}

console.log('\n=== winnability probe (greedy policy, 60 turns, endless off) ===');
for (const seed of [1337, 2, 55, 4242, 9001]) {
  const st = A.newState(seed);
  for (let i = 0; i < 60 && st.phase === 'play'; i++) {
    A.policyTurn(st);
    A.endTurn(st);
    let g = 0;
    while (st.pending && g++ < 8) A.resolveChoice(st, A.bestAiChoice(st));
  }
  console.log('seed ' + String(seed).padEnd(6) + ' phase=' + st.phase.padEnd(4) +
    ' turn=' + st.turn + ' pop=' + A.pop(st) + ' research=' + st.done.length +
    ' food=' + st.res.food + ' water=' + st.res.water + ' scrip=' + st.res.scrip +
    ' score=' + A.score(st).total);
}

console.log('\n=== do-nothing probe (should lose: difficulty is not trivial) ===');
for (const seed of [1337, 4242]) {
  const st = A.newState(seed);
  for (let i = 0; i < 60 && st.phase === 'play'; i++) {
    A.endTurn(st);
    let g = 0;
    while (st.pending && g++ < 8) A.resolveChoice(st, 0);
  }
  console.log('seed ' + seed + ' phase=' + st.phase + ' turn=' + st.turn + ' pop=' + A.pop(st));
}
